        "Delete Keychain Backup": "Sleutelhangerback-up verwijderen",
        "Sessions are encrypted with AES-256 and stored in this device's Keychain. Sessions never leave your device.\n\nIMPORTANT: To restore sessions on a new device or after an OS reset, encrypted OS backups must be enabled, otherwise Keychain data will be lost.\n\nNOTE: Sessions can still be logged out by Telegram or from another device.": "Sessies worden versleuteld met AES-256 en bewaard in de sleutelhanger van dit apparaat. Sessies verlaten je apparaat nooit.\n\nBELANGRIJK: om sessies op een nieuw apparaat of na een systeemreset te herstellen, moeten versleutelde systeemback-ups aanstaan, anders gaan de sleutelhangergegevens verloren.\n\nLET OP: sessies kunnen nog steeds door Telegram of vanaf een ander apparaat worden uitgelogd.",
