        "Current account data will be replaced with backup data. A safety snapshot is created before replacement. After preparation, the app must be restarted.": "De huidige accountgegevens worden vervangen door die uit de back-up. Vóór het vervangen wordt een veiligheidskopie gemaakt. Na de voorbereiding moet de app opnieuw worden gestart.",
        "Restore": "Herstellen",
