        "Delete": "Verwijderen",
        "Backup deleted.": "Back-up verwijderd.",
        "Sessions are encrypted and stored in this device's Keychain. Sessions never leave your device.\n\nIMPORTANT: To restore sessions on a new device or after a system reset, you MUST enable encrypted OS backups, otherwise the Keychain will be lost on restore.\n\nNOTE: Sessions can still be logged out by Telegram itself or from another device.": "Sessies worden versleuteld en bewaard in de sleutelhanger van dit apparaat. Sessies verlaten je apparaat nooit.\n\nBELANGRIJK: om sessies op een nieuw apparaat of na een systeemreset te herstellen, MOET je versleutelde systeemback-ups aanzetten, anders gaat de sleutelhanger bij het herstellen verloren.\n\nLET OP: sessies kunnen nog steeds door Telegram zelf of vanaf een ander apparaat worden uitgelogd.",
