        "Sessions are encrypted with AES-256 and stored in this device's Keychain. Sessions never leave your device.\n\nIMPORTANT: To restore sessions on a new device or after an OS reset, encrypted OS backups must be enabled, otherwise Keychain data will be lost.\n\nNOTE: Sessions can still be logged out by Telegram or from another device.": "Sesi dienkripsi dengan AES-256 dan disimpan di Keychain perangkat ini. Sesi tidak pernah meninggalkan perangkatmu.\n\nPENTING: untuk memulihkan sesi di perangkat baru atau setelah sistem direset, cadangan sistem terenkripsi harus aktif; jika tidak, data Keychain akan hilang.\n\nCATATAN: sesi masih bisa dikeluarkan oleh Telegram atau dari perangkat lain.",
