        "Delete Keychain Backup": "Выдаліць рэзервовую копію з Keychain",
        "Sessions are encrypted with AES-256 and stored in this device's Keychain. Sessions never leave your device.\n\nIMPORTANT: To restore sessions on a new device or after an OS reset, encrypted OS backups must be enabled, otherwise Keychain data will be lost.\n\nNOTE: Sessions can still be logged out by Telegram or from another device.": "Сесіі шыфруюцца (AES-256) і захоўваюцца ў Keychain прылады. Сесіі ніколі не пакідаюць вашу прыладу.\n\nВАЖНА: Каб аднавіць сесіі на новай прыладзе або пасля скіду сістэмы, АБАВЯЗКОВА ўключыце шыфраванне рэзервовых копій АС, інакш Keychain будзе страчаны пры аднаўленні.\n\nЗАЎВАГА: Сесіі ўсё яшчэ могуць быць разлагінены самім Telegram або з іншай прылады.",
