        "Back Up to Keychain": "Резервна копія в Keychain",
        "Restore from Keychain": "Відновити з Keychain",
        "Delete Keychain Backup": "Видалити резервну копію з Keychain",
        "Sessions are encrypted with AES-256 and stored in this device's Keychain. Sessions never leave your device.\n\nIMPORTANT: To restore sessions on a new device or after an OS reset, encrypted OS backups must be enabled, otherwise Keychain data will be lost.\n\nNOTE: Sessions can still be logged out by Telegram or from another device.": "Сесії шифруються (AES-256) і зберігаються в Keychain пристрою. Сесії ніколи не залишають ваш пристрій.\n\nВАЖЛИВО: Щоб відновити сесії на новому пристрої або після скидання системи, ОБОВ’ЯЗКОВО увімкніть шифрування резервних копій ОС, інакше Keychain буде втрачено під час відновлення.\n\nПРИМІТКА: Сесії все ще можуть бути розлогінені самим Telegram або з іншого пристрою.",
        "STATUS": "СТАН",
        "Operation in progress...": "Виконується операція...",
        "Backup is ready to restore.\nRestart the app to apply it.": "Резервну копію підготовлено до відновлення.\nПерезапустіть застосунок, щоб застосувати.",
        "No backup has been created yet.": "Резервну копію ще не створено.",
