        "Size": "Розмір",
        "Create Backup?": "Створити резервну копію?",
        "Current sessions will be encrypted and saved to this device's Keychain.": "Поточні сесії буде зашифровано та збережено в Keychain пристрою.",
        "Create": "Створити",
        "Done": "Готово",
        "Error": "Помилка",
        "Backup created. Accounts": "Резервну копію створено. Акаунтів",
        "Restore from Backup?": "Відновити з резервної копії?",
        "Current account data will be replaced with backup data. A safety snapshot is created before replacement. After preparation, the app must be restarted.": "Поточні дані акаунтів буде замінено даними з резервної копії. Перед заміною створюється захисний знімок. Після підготовки знадобиться перезапуск застосунку.",
        "Restore": "Відновити",
        "Backup Ready": "Резервну копію підготовлено",
        "Fully close and restart the app to finish restoring.": "Повністю закрийте та перезапустіть застосунок, щоб завершити відновлення.",
        "Delete Backup?": "Видалити резервну копію?",
        "The encrypted backup and Keychain key will be deleted. This cannot be undone.": "Зашифровану резервну копію та ключ з Keychain буде видалено. Дію неможливо скасувати.",
        "Delete": "Видалити",
        "Backup deleted.": "Резервну копію видалено.",
        "Sessions are encrypted and stored in this device's Keychain. Sessions never leave your device.\n\nIMPORTANT: To restore sessions on a new device or after a system reset, you MUST enable encrypted OS backups, otherwise the Keychain will be lost on restore.\n\nNOTE: Sessions can still be logged out by Telegram itself or from another device.": "Сесії шифруються та зберігаються в Keychain пристрою. Сесії ніколи не залишають ваш пристрій.\n\nВАЖЛИВО: Щоб відновити сесії на новому пристрої або після скидання системи, ви МУСИТЕ увімкнути шифрування резервних копій ОС, інакше Keychain буде втрачено під час відновлення.\n\nПРИМІТКА: Сесії все ще можуть бути розлогінені самим Telegram або з іншого пристрою.",
        "Please wait…": "Зачекайте…",
        "Backup created. Accounts: ": "Резервну копію створено. Акаунтів: ",
