        // Account backup / session backup screens.
        "Back Up to Keychain": "Copia de seguridad en el Keychain",
        "Restore from Keychain": "Restaurar desde el Keychain",
        "Delete Keychain Backup": "Eliminar la copia del Keychain",
        "Sessions are encrypted with AES-256 and stored in this device's Keychain. Sessions never leave your device.\n\nIMPORTANT: To restore sessions on a new device or after an OS reset, encrypted OS backups must be enabled, otherwise Keychain data will be lost.\n\nNOTE: Sessions can still be logged out by Telegram or from another device.": "Las sesiones se cifran (AES-256) y se guardan en el Keychain de este dispositivo. Las sesiones nunca salen de tu dispositivo.\n\nIMPORTANTE: Para restaurar las sesiones en un dispositivo nuevo o tras restablecer el sistema, deben estar activadas las copias de seguridad cifradas del sistema; de lo contrario, se perderán los datos del Keychain.\n\nNOTA: Telegram u otro dispositivo aún pueden cerrar estas sesiones.",
        "STATUS": "ESTADO",
        "Operation in progress...": "Operación en curso...",
        "Backup is ready to restore.\nRestart the app to apply it.": "La copia está lista para restaurarse.\nReinicia la app para aplicarla.",
