        "Create Backup?": "¿Crear una copia?",
        "Current sessions will be encrypted and saved to this device's Keychain.": "Las sesiones actuales se cifrarán y se guardarán en el Keychain de este dispositivo.",
        "Create": "Crear",
        "Done": "Listo",
        "Error": "Error",
        "Backup created. Accounts": "Copia creada. Cuentas",
        "Restore from Backup?": "¿Restaurar desde la copia?",
        "Current account data will be replaced with backup data. A safety snapshot is created before replacement. After preparation, the app must be restarted.": "Los datos actuales de las cuentas se reemplazarán con los de la copia. Antes del reemplazo se crea una instantánea de seguridad. Tras la preparación habrá que reiniciar la app.",
        "Restore": "Restaurar",
        "Backup Ready": "Copia lista",
        "Fully close and restart the app to finish restoring.": "Cierra por completo y reinicia la app para terminar la restauración.",
        "Delete Backup?": "¿Eliminar la copia?",
        "The encrypted backup and Keychain key will be deleted. This cannot be undone.": "Se eliminarán la copia cifrada y la clave del Keychain. Esta acción no se puede deshacer.",
        "Delete": "Eliminar",
        "Backup deleted.": "Copia eliminada.",
        "Sessions are encrypted and stored in this device's Keychain. Sessions never leave your device.\n\nIMPORTANT: To restore sessions on a new device or after a system reset, you MUST enable encrypted OS backups, otherwise the Keychain will be lost on restore.\n\nNOTE: Sessions can still be logged out by Telegram itself or from another device.": "Las sesiones se cifran y se guardan en el Keychain de este dispositivo. Las sesiones nunca salen de tu dispositivo.\n\nIMPORTANTE: Para restaurar las sesiones en un dispositivo nuevo o tras restablecer el sistema, DEBES activar las copias de seguridad cifradas del sistema; de lo contrario, se perderá el Keychain al restaurar.\n\nNOTA: Telegram u otro dispositivo aún pueden cerrar estas sesiones.",
        "Please wait…": "Espera…",
        "Backup created. Accounts: ": "Copia creada. Cuentas: ",
        "Restore from backup?": "¿Restaurar desde la copia?",
        "Account data will be replaced with the backup. The app must be restarted after preparation.": "Los datos de las cuentas se reemplazarán con los de la copia. Tras la preparación habrá que reiniciar la app.",
        "Fully close and reopen the app to finish restoring.": "Cierra por completo y vuelve a abrir la app para terminar la restauración.",
        "Delete backup?": "¿Eliminar la copia?",
