        // Account backup / session backup screens.
        "Back Up to Keychain": "Sauvegarder dans le trousseau",
        "Restore from Keychain": "Restaurer depuis le trousseau",
        "Delete Keychain Backup": "Supprimer la sauvegarde du trousseau",
        "Sessions are encrypted with AES-256 and stored in this device's Keychain. Sessions never leave your device.\n\nIMPORTANT: To restore sessions on a new device or after an OS reset, encrypted OS backups must be enabled, otherwise Keychain data will be lost.\n\nNOTE: Sessions can still be logged out by Telegram or from another device.": "Les sessions sont chiffrées (AES-256) et stockées dans le trousseau de cet appareil. Elles ne quittent jamais votre appareil.\n\nIMPORTANT : pour restaurer les sessions sur un nouvel appareil ou après une réinitialisation du système, les sauvegardes système chiffrées doivent être activées, sinon les données du trousseau seront perdues.\n\nREMARQUE : Telegram ou un autre appareil peuvent toujours déconnecter ces sessions.",
        "STATUS": "ÉTAT",
        "Operation in progress...": "Opération en cours...",
        "Backup is ready to restore.\nRestart the app to apply it.": "La sauvegarde est prête à être restaurée.\nRedémarrez l’app pour l’appliquer.",
        "No backup has been created yet.": "Aucune sauvegarde n’a encore été créée.",
        "Sessions": "Sessions",
        "No active sessions": "Aucune session active",
        "Logged in": "Connecté",
        "Logged out": "Déconnecté",
        "Last backup: ": "Dernière sauvegarde : ",
        "Account": "Compte",
        "Backup from": "Sauvegarde du",
        "Accounts": "Comptes",
        "Size": "Taille",
        "Create Backup?": "Créer une sauvegarde ?",
        "Current sessions will be encrypted and saved to this device's Keychain.": "Les sessions actuelles seront chiffrées et enregistrées dans le trousseau de cet appareil.",
        "Create": "Créer",
        "Done": "Terminé",
        "Error": "Erreur",
        "Backup created. Accounts": "Sauvegarde créée. Comptes",
        "Restore from Backup?": "Restaurer depuis la sauvegarde ?",
        "Current account data will be replaced with backup data. A safety snapshot is created before replacement. After preparation, the app must be restarted.": "Les données actuelles des comptes seront remplacées par celles de la sauvegarde. Un instantané de sécurité est créé avant le remplacement. Après la préparation, l’app devra être redémarrée.",
        "Restore": "Restaurer",
        "Backup Ready": "Sauvegarde prête",
        "Fully close and restart the app to finish restoring.": "Fermez complètement l’app et redémarrez-la pour terminer la restauration.",
        "Delete Backup?": "Supprimer la sauvegarde ?",
        "The encrypted backup and Keychain key will be deleted. This cannot be undone.": "La sauvegarde chiffrée et la clé du trousseau seront supprimées. Cette action est irréversible.",
        "Delete": "Supprimer",
        "Backup deleted.": "Sauvegarde supprimée.",
        "Sessions are encrypted and stored in this device's Keychain. Sessions never leave your device.\n\nIMPORTANT: To restore sessions on a new device or after a system reset, you MUST enable encrypted OS backups, otherwise the Keychain will be lost on restore.\n\nNOTE: Sessions can still be logged out by Telegram itself or from another device.": "Les sessions sont chiffrées et stockées dans le trousseau de cet appareil. Elles ne quittent jamais votre appareil.\n\nIMPORTANT : pour restaurer les sessions sur un nouvel appareil ou après une réinitialisation du système, vous DEVEZ activer les sauvegardes système chiffrées, sinon le trousseau sera perdu à la restauration.\n\nREMARQUE : Telegram ou un autre appareil peuvent toujours déconnecter ces sessions.",
        "Please wait…": "Veuillez patienter…",
        "Backup created. Accounts: ": "Sauvegarde créée. Comptes : ",
        "Restore from backup?": "Restaurer depuis la sauvegarde ?",
        "Account data will be replaced with the backup. The app must be restarted after preparation.": "Les données des comptes seront remplacées par celles de la sauvegarde. Après la préparation, l’app devra être redémarrée.",
        "Fully close and reopen the app to finish restoring.": "Fermez complètement l’app et rouvrez-la pour terminer la restauration.",
        "Delete backup?": "Supprimer la sauvegarde ?",
        "The encrypted backup and its key will be removed from the Keychain. This cannot be undone.": "La sauvegarde chiffrée et sa clé seront supprimées du trousseau. Cette action est irréversible.",
        "Restart": "Redémarrer",
